parts.text:
Use `#[serde(rename = "...")]` when your Rust field name differs from the CSV header:

```rust
use chrono::NaiveDate;
use serde::Deserialize;

#[derive(Debug, Deserialize)]
pub struct VendaCsv {
    #[serde(rename = "id_loja")]
    pub store_id: String,

    #[serde(rename = "faturamento_bruto")]
    pub gross_revenue: rust_decimal::Decimal,

    #[serde(rename = "num_tickets")]
    pub ticket_count: u32,

    #[serde(deserialize_with = "deserialize_date")]
    pub date: NaiveDate,
}
```

The CSV header `id_loja` is mapped to `store_id`, `faturamento_bruto` to `gross_revenue`, and so on. Headers not represented in the struct are ignored by `csv`.

For dates, `chrono::NaiveDate` can live directly in the struct, but this dataset has multiple date formats. Add a custom deserializer:

```rust
use chrono::NaiveDate;
use serde::{Deserialize, Deserializer};
use serde::de::Error;

const DATE_FORMATS: [&str; 3] = [
    "%Y-%m-%d", // 2026-06-30
    "%d/%m/%Y", // 30/06/2026
    "%d.%m.%Y", // 30.06.2026
];

fn deserialize_date<'de, D>(deserializer: D) -> Result<NaiveDate, D::Error>
where
    D: Deserializer<'de>,
{
    let value = String::deserialize(deserializer)?;

    DATE_FORMATS
        .iter()
        .find_map(|format| NaiveDate::parse_from_str(&value, format).ok())
        .ok_or_else(|| D::Error::custom(format!("data inválida: {value}")))
}
```

For nullable date fields, use `Option<NaiveDate>` and a separate function:

```rust
fn deserialize_optional_date<'de, D>(
    deserializer: D,
) -> Result<Option<NaiveDate>, D::Error>
where
    D: Deserializer<'de>,
{
    let value = Option::<String>::deserialize(deserializer)?;

    match value.as_deref().map(str::trim).filter(|value| !value.is_empty()) {
        None => Ok(None),
        Some(value) => DATE_FORMATS
            .iter()
            .find_map(|format| NaiveDate::parse_from_str(value, format).ok())
            .map(Some)
            .ok_or_else(|| D::Error::custom(format!("data inválida: {value}"))),
    }
}
```

Use `NaiveDate`, not `DateTime`, because the CSV data has dates without time zone or time-of-day.

