use std::{fs::File, path::PathBuf};

use anyhow::Result;
use api::{
    indicator::StoreIndicators,
    model::{DailySale, Product, Rating, Store},
};
use axum::{Router, routing::get};
use csv::Reader;

fn get_csv_reader(table_name: &str) -> Result<Reader<File>> {
    let path =
        PathBuf::from(env!("CARGO_MANIFEST_DIR")).join(format!("../data/{}.csv", table_name));
    Ok(csv::Reader::from_path(path)?)
}

async fn list_stores() -> Result<Vec<Store>> {
    todo!()
}

#[tokio::main]
async fn main() -> Result<()> {
    let app = Router::new().route("/api/stores", get(list_stores));

    let mut stores = get_csv_reader("turmalina_lojas")?;
    let stores: Vec<Store> = stores.deserialize().collect::<Result<_, _>>()?;

    let mut products = get_csv_reader("turmalina_itens")?;
    let products: Vec<Product> = products.deserialize().collect::<Result<_, _>>()?;

    let mut ratings = get_csv_reader("turmalina_avaliacoes")?;
    let ratings: Vec<Rating> = ratings.deserialize().collect::<Result<_, _>>()?;

    let mut daily_sales = get_csv_reader("turmalina_vendas_diarias")?;
    let daily_sales: Vec<DailySale> = daily_sales.deserialize().collect::<Result<_, _>>()?;

    let mut indicators: Vec<_> = stores
        .iter()
        .filter(|store| store.status)
        .filter_map(|store| {
            match StoreIndicators::from_general_data(store, &daily_sales, &products, &ratings) {
                Ok(indicators) => Some(indicators),
                Err(e) => {
                    eprintln!("{}", e);
                    None
                }
            }
        })
        .collect();

    indicators.sort_unstable_by(|left, right| {
        right
            .intervention_score
            .cmp(&left.intervention_score)
            .then_with(|| {
                left.net_sales_per_calendar_day
                    .cmp(&right.net_sales_per_calendar_day)
            })
    });

    println!("{:?}", indicators);

    Ok(())
}

