+        .iter()
+        .find(|store| store.store_id.eq_ignore_ascii_case(&store_id))
+        .cloned()
+        .map(Json)
+        .ok_or(StatusCode::NOT_FOUND)
+}
+
+async fn list_indicators(State(state): State<AppState>) -> Json<Vec<StoreIndicators>> {
+    Json(state.indicators.as_ref().clone())
+}
+
