+        .cloned()
+        .map(Json)
+        .ok_or(StatusCode::NOT_FOUND)
+}
+
+#[tokio::main]
+async fn main() -> Result<()> {
+    let mut stores_reader = get_csv_reader("turmalina_lojas")?;
