+    indicators.sort_unstable_by(|left, right| {
+        right
+            .intervention_score
+            .cmp(&left.intervention_score)
+            .then_with(|| {
+                left.net_sales_per_calendar_day
+                    .cmp(&right.net_sales_per_calendar_day)
+            })
+    });
+
+    let state = AppState {
+        stores: Arc::new(stores),
+        indicators: Arc::new(indicators),
+    };
