import { useEffect, useState } from "react";

type Store = {
    id_loja: string;
    nome_loja: string;
    cidade_uf: string;
    formato: string;
    modelo: string;
    data_abertura: string;
    status: boolean;
};
type Product = { name: string; quantity_sold: number; estimated_sales: string };
type Indicator = {
    store_id: string;
    intervention_score: number;
    days_without_opening: number;
    net_sales_per_calendar_day: string;
    net_sales_per_calendar_day_change_pct: string;
    ingredient_margin_pct: string;
    ingredient_margin_change_percentage_points: string;
    net_sales_per_team_hour: string | null;
    net_sales_per_team_hour_change_pct: string | null;
    waste_pct_of_net_sales: string | null;
    average_net_ticket: string | null;
    valid_rating_count: number;
    average_rating: string | null;
    median_wait_time_minutes: number | null;
    top_selling_products: Product[];
};
type DashboardStore = Store & { indicator: Indicator };
type Tab = "overview" | "stores" | "margin" | "team" | "expansion";

const API_URL = import.meta.env.PUBLIC_API_URL ?? "http://127.0.0.1:3000";
const money = new Intl.NumberFormat("pt-BR", {
    style: "currency",
    currency: "BRL",
    maximumFractionDigits: 0,
});
const number = new Intl.NumberFormat("pt-BR", { maximumFractionDigits: 1 });
const tabs: Array<[Tab, string]> = [
    ["overview", "Visão geral"],
    ["stores", "Lojas"],
    ["margin", "Margem e desperdício"],
    ["team", "Equipe e cliente"],
    ["expansion", "Expansão e qualidade"],
];

function value(input: string | null | undefined) {
    const parsed = Number(input);
    return input === null || input === undefined || Number.isNaN(parsed)
        ? null
        : parsed;
}
function average(values: Array<number | null>) {
    const valid = values.filter((item): item is number => item !== null);
    return valid.length
        ? valid.reduce((sum, item) => sum + item, 0) / valid.length
        : null;
}
function percent(input: string | null, suffix = "%") {
    const metric = value(input);
    return metric === null
        ? "—"
        : `${metric > 0 ? "+" : ""}${number.format(metric)}${suffix}`;
}
function metricClass(input: string | null, inverse = false) {
    const metric = value(input);
    return metric === null || metric === 0
        ? "text-slate-500"
        : (inverse ? metric < 0 : metric > 0)
          ? "text-emerald-700"
          : "text-rose-700";
}
function quartile(values: Array<number | null>, position: 0.25 | 0.75) {
    const sorted = values
        .filter((item): item is number => item !== null)
        .sort((left, right) => left - right);
    return sorted.length
        ? sorted[Math.floor((sorted.length - 1) * position)]
        : null;
}
function reasons(store: DashboardStore, stores: DashboardStore[]) {
    const indicator = store.indicator;
    const result: string[] = [];
    if ((value(indicator.net_sales_per_calendar_day_change_pct) ?? 0) < -5)
        result.push(
            `Vendas/dia ${percent(indicator.net_sales_per_calendar_day_change_pct)}`,
        );
    if ((value(indicator.ingredient_margin_change_percentage_points) ?? 0) < -2)
        result.push(
            `Margem ${percent(indicator.ingredient_margin_change_percentage_points, " pp")}`,
        );
    if ((value(indicator.net_sales_per_team_hour_change_pct) ?? 0) < -5)
        result.push(
            `Produtividade ${percent(indicator.net_sales_per_team_hour_change_pct)}`,
        );
    const wasteThreshold = quartile(
        stores.map((item) => value(item.indicator.waste_pct_of_net_sales)),
        0.75,
    );
    const ratingThreshold = quartile(
        stores.map((item) => value(item.indicator.average_rating)),
        0.25,
    );
    const waitThreshold = quartile(
        stores.map((item) => item.indicator.median_wait_time_minutes),
        0.75,
    );
    if (
        wasteThreshold !== null &&
        (value(indicator.waste_pct_of_net_sales) ?? -Infinity) >= wasteThreshold
    )
        result.push(
            `Desperdício ${number.format(value(indicator.waste_pct_of_net_sales)!)}%`,
        );
    if (
        indicator.valid_rating_count >= 10 &&
        ((ratingThreshold !== null &&
            (value(indicator.average_rating) ?? Infinity) <= ratingThreshold) ||
            (waitThreshold !== null &&
                (indicator.median_wait_time_minutes ?? -Infinity) >=
                    waitThreshold))
    )
        result.push(
            `Cliente: ${indicator.average_rating ? `${number.format(value(indicator.average_rating) ?? 0)}/5` : `${indicator.median_wait_time_minutes} min`}`,
        );
    const visible = result.slice(0, indicator.intervention_score);
    while (visible.length < indicator.intervention_score)
        visible.push("Sinal adicional calculado pela API");
    return visible;
}

