                                    eyebrow="Rentabilidade operacional"
                                    title="Margem e desperdício"
                                    note="Margem após insumos não é lucro: não inclui mão de obra, aluguel, impostos ou custos fixos."
                                />
                                <div className="mt-5 grid gap-4 md:grid-cols-3">
                                    <Card
                                        label="Margem média"
                                        value={
                                            margin === null
